window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[244]={"id":"244","numero":244,"titre":"Adénome hypophysaire","objectifs":[{"id":"244-1","rang":"A","rubrique":"Diagnostic positif","titre":"Identifier les éléments d’un syndrome tumoral neuro-hypophysaire","contenu":"<p>L'<span class=\"kw-def\">adénome hypophysaire</span> est une <strong>tumeur bénigne</strong> développée aux dépens de l'hypophyse. Il se révèle par trois mécanismes : un <span class=\"kw-def\">syndrome tumoral</span> (compression des structures de voisinage), un <span class=\"kw-def\">syndrome d'hypersécrétion hormonale</span> et un <span class=\"kw-def\">syndrome d'insuffisance antéhypophysaire</span>. Cet objectif porte sur le <strong>syndrome <span class=\"kw-etio\">tumoral</span></strong>, conséquence directe de l'effet de <span class=\"kw-clinique\">masse</span>.</p>\n      <table >\n        <thead>\n          <tr><th>Élément</th><th>Description</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Céphalées</span></strong></td>\n            <td>Typiquement <span class=\"kw-clinique\">rétro-orbitaires</span> et <span class=\"kw-clinique\">localisées</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Troubles visuels</strong></td>\n            <td>\n              Par compression des voies optiques (le <span class=\"kw-def\">chiasma optique</span> est à quelques mm au-dessus de l'hypophyse).<br>\n              <strong>Signes fonctionnels :</strong> <span class=\"kw-clinique\">gêne visuelle</span> ; <span class=\"kw-clinique\">voile devant les yeux</span> ; difficulté à fixer un point ; sensation qu'il manque un mot à la lecture<br>\n              <strong>Champ visuel</strong> (appareil de Goldmann ou périmétrie cinétique automatisée) : <span class=\"kw-clinique\">quadranopsie bitemporale supérieure</span> (compression de la partie antérieure du chiasma) ; puis <span class=\"kw-clinique\">hémianopsie bitemporale</span> à un <span class=\"kw-def\">stade</span> plus tardif\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-alerte\">Hypertension intracrânienne</span></strong> (exceptionnelle)</td>\n            <td>Tableau rare (LiSA) : <span class=\"kw-clinique\">céphalées tenaces</span>, <span class=\"kw-clinique\">nausées/vomissements en jet</span>, <span class=\"kw-clinique\">mydriase bilatérale</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Signes négatifs</strong></td>\n            <td>\n              <span class=\"kw-clinique\">Acuité visuelle</span> le plus souvent <strong>normale</strong> (pas d'atteinte du champ visuel central — diminuée seulement si <span class=\"kw-clinique\">lésion</span> très volumineuse, négligée).<br>\n              <span class=\"kw-clinique\">Fond d'œil</span> normal le plus souvent.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">\n        <strong>Apoplexie hypophysaire.</strong> Tableau <span class=\"kw-alerte\">brutal</span> (adénome en voie de <span class=\"kw-clinique\">nécrose</span> ou hémorragie), justifiant une imagerie et une prise en charge neurochirurgicale en <span class=\"kw-alerte\">urgence</span> :\n        <ul>\n          <li><span class=\"kw-clinique\">Céphalées violentes</span></li>\n          <li><span class=\"kw-clinique\">Hémianopsie bitemporale</span> (compression chiasmatique aiguë)</li>\n          <li><span class=\"kw-clinique\">Photophobie</span> (pseudo-<span class=\"kw-def\">syndrome méningé</span>)</li>\n          <li><span class=\"kw-alerte\">Syndrome caverneux</span> : paralysie oculomotrice ; ptosis ; diplopie</li>\n          <li><span class=\"kw-clinique\">Syndrome confusionnel</span>, voire <span class=\"kw-alerte\">coma</span></li>\n          <li><span class=\"kw-alerte\">Insuffisance corticotrope aiguë</span> (insuffisance surrénale aiguë)</li>\n          <li>Hémorragie sous-arachnoïdienne possible</li>\n        </ul>\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 100 — <span class=\"kw-clinique\">Céphalée</span> · 81 — Altération chronique de la vision</em></p>","frequence":1},{"id":"244-2","rang":"A","rubrique":"Diagnostic positif","titre":"Identifier les signes cliniques orientant vers une hypersécrétion anté-hypophysaire","contenu":"<p><span class=\"kw-chiffre\">75 %</span> des <span class=\"kw-def\">adénomes hypophysaires</span> sont <strong>sécrétants</strong>. Le tableau clinique de l'hypersécrétion dépend de la <span class=\"kw-def\">lignée cellulaire</span> <span class=\"kw-etio\">tumorale</span>.</p>\n      <table >\n        <thead>\n          <tr><th>Hormone</th><th>Signes cliniques évocateurs</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Prolactine</strong><br>(<span class=\"kw-def\">prolactinome</span>)</td>\n            <td>\n              <strong>Galactorrhée :</strong> provoquée (<span class=\"kw-chiffre\">80 %</span>) ou spontanée<br>\n              <strong>Hypogonadisme hypogonadotrope :</strong> la PRL inhibe la sécrétion pulsatile de <span class=\"kw-def\">GnRH</span> — femme : <span class=\"kw-clinique\">aménorrhée</span>, oligo/spanioménorrhée, baisse de libido, <span class=\"kw-clinique\">dyspareunie</span>, anovulation, <span class=\"kw-clinique\">infertilité</span> ; homme : <span class=\"kw-clinique\">gynécomastie</span>, baisse de libido, <span class=\"kw-clinique\">dysfonction érectile</span><br>\n              <strong>Os :</strong> risque d'<span class=\"kw-alerte\">ostéoporose</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>GH</strong><br>(<span class=\"kw-def\">acromégalie</span>)</td>\n            <td>\n              <strong>Syndrome dysmorphique :</strong> <span class=\"kw-clinique\">extrémités élargies</span> (mains, pieds, doigts boudinés) ; visage (nez élargi, pommettes saillantes, front bombé, lèvres épaisses, <span class=\"kw-clinique\">prognathisme</span>) ; <span class=\"kw-clinique\">gigantisme</span> si hypersécrétion avant la puberté<br>\n              <strong>Signes généraux :</strong> <span class=\"kw-clinique\"><span class=\"kw-clinique\">sueurs</span> nocturnes</span> malodorantes ; <span class=\"kw-clinique\">céphalées</span> ; <span class=\"kw-clinique\">syndrome du canal carpien</span> ; <span class=\"kw-clinique\">arthralgies</span> ; <span class=\"kw-clinique\">HTA</span> (<span class=\"kw-chiffre\">50 %</span>) ; <span class=\"kw-clinique\">syndrome d'apnées du sommeil</span><br>\n              <strong>Complications :</strong> <span class=\"kw-alerte\">diabète</span> / <span class=\"kw-ci\">intolérance</span> au glucose ; <span class=\"kw-alerte\">hypertrophie myocardique</span> (1<sup>re</sup> cause de <span class=\"kw-def\">mortalité</span>, par <span class=\"kw-def\">insuffisance cardiaque</span>) ; polypes coliques (<span class=\"kw-alerte\">risque de cancer colorectal</span>)\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-bio\">ACTH</span></strong><br>(<span class=\"kw-def\">maladie de Cushing</span>)</td>\n            <td>\n              Adénome corticotrope = cause la plus fréquente de <span class=\"kw-def\">syndrome de Cushing</span> hors <span class=\"kw-etio\">iatrogène</span>.<br>\n              <strong>Signes spécifiques :</strong> <span class=\"kw-clinique\">érythrose faciale</span> ; <span class=\"kw-clinique\">amyotrophie</span> proximale (ceintures, abdomen) ; atrophie cutanée « en papier à cigarette » ; <span class=\"kw-clinique\">ecchymoses</span> au moindre <span class=\"kw-alerte\">choc</span> ; <span class=\"kw-clinique\">vergetures pourpres</span> larges (<span class=\"kw-chiffre\">&gt; 1 cm</span>), horizontales<br>\n              <strong>Signes moins spécifiques :</strong> prise pondérale <span class=\"kw-clinique\">facio-tronculaire</span> ; « bosse de bison » ; visage arrondi, bouffi<br>\n              <strong><span class=\"kw-def\">Comorbidités</span> :</strong> <span class=\"kw-clinique\">HTA</span> ; <span class=\"kw-alerte\">diabète</span> ; <span class=\"kw-bio\">hypokaliémie</span> ; <span class=\"kw-alerte\">ostéoporose</span> ; troubles gonadiques et psychiatriques\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-bio\">TSH</span></strong><br>(adénome thyréotrope)</td>\n            <td><span class=\"kw-clinique\">Hyperthyroïdie</span> par hypersécrétion de <span class=\"kw-bio\">TSH</span> avec <strong>goitre homogène</strong> et syndrome tumoral hypophysaire ; entité <strong>rare</strong>.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-bio\">LH / FSH</span></strong><br>(adénome gonadotrope)</td>\n            <td>\n              Les adénomes gonadotropes représentent la <strong>majorité des adénomes hypophysaires</strong> mais se présentent comme des adénomes <span class=\"kw-def\">cliniquement non fonctionnels</span> (sécrétion non pulsatile de sous-unités inactives).<br>\n              <strong>Exceptionnellement</strong> : <span class=\"kw-clinique\">hyperstimulation ovarienne</span> avec algies pelviennes et macrokystes ovariens chez la femme ; <span class=\"kw-clinique\">macro-orchidie</span> chez l'homme.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/244/cushing-anomalies-morphologiques.png\" alt=\"Schéma des anomalies morphologiques du syndrome de Cushing : visage rond et rouge, bosse de bison, comblement des creux sus-claviculaires, augmentation du tour de taille, vergetures rouges, amyotrophie et faiblesse musculaire des membres, ecchymoses, peau fine et fragile\" loading=\"lazy\">\n        <figcaption>Anomalies morphologiques du <span class=\"kw-def\">syndrome de Cushing</span> — visage arrondi érythrosique, « bosse de bison », comblement des creux sus-claviculaires, répartition facio-tronculaire des graisses, amyotrophie des membres, fragilité cutanée (<span class=\"kw-clinique\">ecchymoses</span>, vergetures). Source : fiche source EDN item 244 (<span class=\"kw-def\">Syndrome de Cushing</span>).</figcaption>\n      </figure>\n      <div class=\"callout callout-info\">\n        <strong>Piège.</strong> L'<span class=\"kw-def\">acromégalie</span> n'est <strong>pas</strong> responsable d'<span class=\"kw-etio\">obésité</span> (contraste avec le <span class=\"kw-def\">syndrome de Cushing</span>). Le <span class=\"kw-alerte\">diabète</span> y est en revanche fréquent, la GH étant une hormone hyperglycémiante.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 247 — <span class=\"kw-def\">Diabète</span> · 242 — <span class=\"kw-def\">Hyperthyroïdie</span> · 309 — Tumeurs du poumon</em></p>","frequence":4},{"id":"244-3","rang":"A","rubrique":"Diagnostic positif","titre":"Identifier un tableau d’insuffisance anté-hypophysaire associée","contenu":"<p>L'<span class=\"kw-def\">insuffisance antéhypophysaire</span> résulte de la compression de l'antéhypophyse saine. Le déficit porte généralement sur <strong>toutes</strong> les hormones hypophysaires (<span class=\"kw-def\">panhypopituitarisme</span>). L'installation est <span class=\"kw-alerte\">insidieuse</span>, ce qui rend le diagnostic difficile.</p>\n      <p><strong>Signes cliniques généraux :</strong> <span class=\"kw-clinique\">faciès pâle</span>, un peu vieillot ; <span class=\"kw-clinique\">peau mince, froide, sèche</span> ; cheveux fins et soyeux ; <span class=\"kw-clinique\">dépigmentation</span> des aréoles mammaires et des organes génitaux externes (constante) ; <span class=\"kw-clinique\">dépilation</span> axillaire et pubienne (signe intéressant chez le sujet de moins de <span class=\"kw-chiffre\">60 ans</span>).</p>\n      <table >\n        <thead>\n          <tr><th>Axe</th><th>Manifestations</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Corticotrope</strong></td>\n            <td><span class=\"kw-clinique\">Asthénie</span> ; <span class=\"kw-clinique\">amaigrissement</span> ; <span class=\"kw-clinique\">anorexie</span> ; <span class=\"kw-clinique\">hypotension</span> ; <span class=\"kw-clinique\">hypoglycémie</span> de jeûne ; <span class=\"kw-bio\">hyponatrémie</span> de dilution (SIADH).</td>\n          </tr>\n          <tr>\n            <td><strong>Gonadotrope</strong></td>\n            <td>\n              <strong>Homme :</strong> baisse de libido ; <span class=\"kw-clinique\">dysfonction érectile</span> ; raréfaction de la pilosité ; testicules mous et petits ; <span class=\"kw-clinique\">gynécomastie</span><br>\n              <strong>Femme :</strong> <span class=\"kw-clinique\">aménorrhée</span> sans bouffées de chaleur ; baisse de libido ; <span class=\"kw-clinique\">dyspareunie</span> ; anovulation, infertilité<br>\n              <strong>2 sexes :</strong> déminéralisation osseuse, <span class=\"kw-alerte\">ostéoporose</span> ; avant la puberté : <span class=\"kw-clinique\">impubérisme</span> / retard pubertaire\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Somatotrope</strong></td>\n            <td>Déficit <strong>le plus fréquent</strong> (présent dès qu'un autre axe est déficient) — adulte : diminution de la <span class=\"kw-clinique\">masse</span> et de la force musculaires, <span class=\"kw-clinique\">adiposité abdominale</span>, <span class=\"kw-clinique\">asthénie</span> ; enfant : <span class=\"kw-clinique\">retard de croissance</span>, accidents hypoglycémiques.</td>\n          </tr>\n          <tr>\n            <td><strong>Thyréotrope</strong></td>\n            <td><span class=\"kw-def\">Hypothyroïdie centrale</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Lactotrope</strong></td>\n            <td><span class=\"kw-bio\">Prolactinémie</span> le plus souvent normale ou élevée (par diminution du tonus dopaminergique inhibiteur) ; cliniquement : <strong>absence de montée laiteuse</strong> en post-partum (LiSA).</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> La mise en évidence d'un déficit hypophysaire isolé ou multiple <strong>impose</strong> la réalisation d'une <span class=\"kw-imagerie\">IRM hypophysaire</span>.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 245 — Insuffisance surrénale · 243 — <span class=\"kw-def\">Hypothyroïdie</span> · 246 — Gynécomastie</em></p>","frequence":1},{"id":"244-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes d’un diabète insipide","contenu":"<p>Point clé de l'item : l'<span class=\"kw-def\">adénome hypophysaire</span> ne s'accompagne <strong>jamais</strong> de <span class=\"kw-def\">diabète insipide</span>, car il ne touche que l'<strong>antéhypophyse</strong>. Le <span class=\"kw-def\">diabète</span> insipide central relève de la <strong>posthypophyse</strong> (défaut de sécrétion d'<span class=\"kw-def\">ADH</span>).</p>\n      <p>Dans le contexte d'un adénome, un <span class=\"kw-def\">diabète</span> insipide ne peut survenir que dans deux situations :</p>\n      <ul>\n        <li><strong>Après <span class=\"kw-ttt\">chirurgie</span></strong> d'un adénome hypophysaire ;</li>\n        <li>Lors d'une <span class=\"kw-alerte\">apoplexie hypophysaire</span>.</li>\n      </ul>\n      <p>Quand un <span class=\"kw-def\">diabète insipide central</span> survient (post-chirurgical, apoplexie ou <span class=\"kw-clinique\">lésion</span> non adénomateuse), il se traduit par un <strong><span class=\"kw-def\">syndrome polyuro-polydipsique</span></strong> lié au défaut de sécrétion d'<span class=\"kw-def\">ADH</span> :</p>\n      <table >\n        <thead><tr><th>Signe</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Polyurie hypotonique</span></strong></td>\n            <td>Diurèse <span class=\"kw-chiffre\">&gt; 3 L/jour</span>, urines diluées : osmolalité urinaire <span class=\"kw-chiffre\">&lt; 300 mOsm/L</span> (rapport U/P osm <span class=\"kw-chiffre\">&lt; 1</span>). La <strong>persistance nocturne</strong> de la polyurie (nycturie, réveils nocturnes) est un <strong>bon signe d'organicité</strong>.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Polydipsie</span></strong></td>\n            <td><span class=\"kw-clinique\">Soif</span> intense : les apports hydriques compensent en général la polyurie (boissons équivalentes à la diurèse) et maintiennent une osmolalité plasmatique normale.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-alerte\">Hypernatrémie / déshydratation</span></strong></td>\n            <td>Hyperosmolalité plasmatique avec <span class=\"kw-bio\">hypernatrémie</span> (déshydratation intracellulaire) <strong>uniquement si le patient n'a plus libre accès à l'eau</strong> → risque de déshydratation sévère.</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>Interrogatoire orienté.</strong> Préciser le début et l'ancienneté des troubles, la <span class=\"kw-clinique\">persistance nocturne</span> de la polyurie, les réveils nocturnes, une prise médicamenteuse et le caractère familial du trouble ; quantifier sur le nycthémère les boissons et la diurèse, et rechercher des signes de déshydratation.\n      </div>\n      <div class=\"callout callout-info\">\n        <strong>Valeur d'orientation.</strong> Un <span class=\"kw-def\">diabète insipide central</span> révélant une <span class=\"kw-clinique\">masse</span> de la région hypothalamo-hypophysaire oriente vers une <span class=\"kw-alerte\">lésion non adénomateuse</span> — <span class=\"kw-etio\">métastase</span>, <span class=\"kw-etio\">sarcoïdose</span>, <span class=\"kw-etio\">histiocytose</span>, <span class=\"kw-etio\">tuberculose</span>, <span class=\"kw-etio\">hypophysite auto-immune</span>. C'est un <span class=\"kw-def\">diagnostic différentiel</span> de l'adénome.\n      </div>","frequence":0},{"id":"244-5","rang":"B","rubrique":"Examens complémentaires","titre":"Savoir prescrire un bilan hormonal ante-hypohysaire \"statique\"","contenu":"<p>Le bilan <strong>« statique »</strong> — ou <span class=\"kw-def\">hypophysiogramme</span> — regroupe les dosages hormonaux de base explorant les <strong>5 axes antéhypophysaires</strong>. Il est complété si besoin, sur avis de l'endocrinologue, par des <span class=\"kw-def\">tests dynamiques</span> (hors champ de cet objectif « statique »).</p>\n      <table >\n        <thead>\n          <tr><th>Axe</th><th>Dosages statiques</th><th>Profil d'un déficit central</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Corticotrope</strong></td>\n            <td><span class=\"kw-bio\">Cortisol à 8h</span> ; <span class=\"kw-bio\">ACTH</span></td>\n            <td>Cortisolémie de <span class=\"kw-chiffre\">8h</span> basse (<span class=\"kw-chiffre\">&lt; 5 µg/dL</span> très évocateur) sans élévation de l'<span class=\"kw-bio\">ACTH</span>. Le cortisol de <span class=\"kw-chiffre\">8h</span> ne différencie pas insuffisance surrénale primaire et centrale.</td>\n          </tr>\n          <tr>\n            <td><strong>Gonadotrope</strong></td>\n            <td><span class=\"kw-bio\">Testostérone</span> (homme) ou <span class=\"kw-bio\">œstradiol</span> (femme) ; <span class=\"kw-bio\">LH</span> ; <span class=\"kw-bio\">FSH</span></td>\n            <td>Hormone périphérique basse avec LH/FSH <strong>normales ou basses</strong> (= inappropriées). Chez la femme ménopausée, des gonadotrophines « normales » sont anormales (elles devraient être élevées).</td>\n          </tr>\n          <tr>\n            <td><strong>Somatotrope</strong></td>\n            <td><span class=\"kw-bio\">IGF-1</span></td>\n            <td>Un IGF-1 bas oriente ; la confirmation passe par des tests dynamiques.</td>\n          </tr>\n          <tr>\n            <td><strong>Thyréotrope</strong></td>\n            <td><span class=\"kw-bio\">T4 libre</span> ; <span class=\"kw-bio\">TSH</span></td>\n            <td><span class=\"kw-bio\">T4L</span> basse avec <span class=\"kw-bio\">TSH</span> normale ou basse = <span class=\"kw-def\">hypothyroïdie centrale</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Lactotrope</strong></td>\n            <td><span class=\"kw-bio\">Prolactine</span></td>\n            <td>Prolactinémie normale ou élevée.</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>Piège.</strong> Le dosage <strong>isolé de la GH n'a aucune valeur diagnostique</strong> : sécrétion pulsatile dans le nycthémère (la GH peut être indétectable, basse ou brièvement élevée chez un sujet sain). L'exploration statique de l'axe somatotrope repose sur l'<span class=\"kw-bio\">IGF-1</span>.\n      </div>\n      <div class=\"callout callout-info\">\n        <strong>Principe d'interprétation.</strong> Un axe central déficient montre l'hormone « commande » hypophysaire <strong>basse ou normale-inappropriée</strong> alors que l'hormone périphérique est basse — à l'inverse d'un déficit périphérique, où la commande s'élève (ex. <span class=\"kw-bio\">TSH</span> « normale » non rassurante si la <span class=\"kw-bio\">T4L</span> est basse).\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 245 — Insuffisance surrénale · 243 — <span class=\"kw-def\">Hypothyroïdie</span></em></p>","frequence":4,"liens":[{"href":"https://radiopaedia.org/articles/acromegaly","label":"Radiopaedia : Acromegaly"},{"href":"https://radiopaedia.org/articles/pituitary-mri-an-approach-1","label":"Radiopaedia : Pituitary mri an approach 1"},{"href":"https://radiopaedia.org/articles/pituitary-adenomapitnet","label":"Radiopaedia : Pituitary adenomapitnet"},{"href":"https://radiopaedia.org/cases/normal-brain-mri-6","label":"Radiopaedia : Normal brain mri 6"},{"href":"https://radiopaedia.org/articles/pituitary-microadenoma","label":"Radiopaedia : Pituitary microadenoma"},{"href":"https://radiopaedia.org/articles/pituitary-macroadenoma-1","label":"Radiopaedia : Pituitary macroadenoma 1"},{"href":"https://radiopaedia.org/articles/adamantinomatous-craniopharyngioma","label":"Radiopaedia : Adamantinomatous craniopharyngioma"},{"href":"https://radiopaedia.org/cases/sellar-and-suprasellar-meningioma","label":"Radiopaedia : Sellar and suprasellar meningioma"},{"href":"https://radiopaedia.org/cases/pituitary-hypertrophy-in-pregnancy","label":"Radiopaedia : Pituitary hypertrophy in pregnancy"},{"href":"https://radiopaedia.org/articles/pituitary-metastasis-1","label":"Radiopaedia : Pituitary metastasis 1"},{"href":"https://radiopaedia.org/articles/pituitary-apoplexy","label":"Radiopaedia : Pituitary apoplexy"}]},{"id":"244-6","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les indications de l’IRM hypophysaire en fonction du contexte clinique et biologique","contenu":"<p>L'<span class=\"kw-imagerie\">IRM de l'hypophyse</span> (et non <span class=\"kw-imagerie\">IRM</span> de l'encéphale) est l'examen de <strong>référence</strong> de la région hypothalamo-hypophysaire : coupes millimétriques centrées sur la <span class=\"kw-def\">selle turcique</span>, dans les 3 plans, avec injection de <span class=\"kw-imagerie\">gadolinium</span>. La <span class=\"kw-imagerie\">TDM</span> n'est utilisée qu'en cas de <span class=\"kw-ci\">contre-indication</span> ou d'indisponibilité de l'<span class=\"kw-imagerie\">IRM</span>.</p>\n      <p><strong>Indications selon le contexte :</strong></p>\n      <ul>\n        <li>Syndrome <span class=\"kw-etio\">tumoral</span> hypophysaire (<span class=\"kw-clinique\">céphalées</span>, troubles visuels) ;</li>\n        <li>Syndrome d'hypersécrétion confirmé biologiquement (hyperprolactinémie après exclusion des causes générales et médicamenteuses, acromégalie après <span class=\"kw-bio\">IGF-1</span>, hypercortisolisme ACTH-dépendant…) ;</li>\n        <li>Mise en évidence d'un déficit antéhypophysaire isolé ou multiple → <span class=\"kw-imagerie\">IRM</span> <strong>systématique</strong> ;</li>\n        <li><span class=\"kw-alerte\">Urgence</span> : suspicion d'<span class=\"kw-alerte\">apoplexie hypophysaire</span>.</li>\n      </ul>\n      <p>L'<span class=\"kw-imagerie\">IRM</span> précise la <strong>taille</strong> (<span class=\"kw-def\">microadénome</span> <span class=\"kw-chiffre\">&lt; 10 mm</span> <span class=\"kw-bio\">vs</span> <span class=\"kw-def\">macroadénome</span> <span class=\"kw-chiffre\">&gt; 10 mm</span>), le caractère <strong>envahissant</strong> (sinus caverneux, sinus sphénoïdal, extension suprasellaire) et les rapports avec le <span class=\"kw-def\">chiasma optique</span> et les carotides — informations capitales avant un geste chirurgical.</p>\n      <table >\n        <thead>\n          <tr><th>Critère</th><th>Microadénome (&lt;<span class=\"kw-chiffre\"> 10 mm</span>)</th><th>Macroadénome (&gt;<span class=\"kw-chiffre\"> 10 mm</span>)</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Signal / prise de contraste</strong></td>\n            <td>\n              Image arrondie, homogène.<br>\n              <span class=\"kw-imagerie\">Retard de prise de contraste</span> : T1 sans injection isointense au reste de la glande ; T1 injecté <span class=\"kw-imagerie\">hypo-intense</span> par rapport à l'hypophyse saine.<br>\n              Parfois visible seulement en <span class=\"kw-imagerie\">T2</span> (hypo- ou hypersignal).\n            </td>\n            <td>\n              T1 non injecté : <span class=\"kw-imagerie\">isointense au parenchyme cérébral</span>.<br>\n              T1 injecté : <span class=\"kw-imagerie\">hypo-intense</span> par rapport à l'hypophyse saine, <span class=\"kw-imagerie\">hyperintense</span> par rapport au parenchyme cérébral.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Signes indirects / expansion</strong></td>\n            <td>\n              Bord supérieur de l'hypophyse <span class=\"kw-imagerie\">convexe</span> (bombement).<br>\n              Déviation latérale de la <span class=\"kw-def\">tige pituitaire</span> du côté opposé à la <span class=\"kw-clinique\">lésion</span>.<br>\n              <span class=\"kw-clinique\">Érosion</span> du plancher sellaire ; pas d'<span class=\"kw-bio\">envahissement</span> des structures adjacentes.\n            </td>\n            <td>\n              Expansion à étudier :<br>\n              <strong>En haut :</strong> chiasma optique, voire 3<sup>e</sup> ventricule<br>\n              <strong>En bas :</strong> sinus sphénoïdal<br>\n              <strong>Latéralement :</strong> sinus caverneux\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Un examen ophtalmologique avec <span class=\"kw-clinique\">champ visuel</span> est <strong>systématiquement</strong> associé à l'<span class=\"kw-imagerie\">IRM</span> dans le bilan d'un adénome hypophysaire.\n      </div>","frequence":3},{"id":"244-7","rang":"B","rubrique":"Diagnostic positif","titre":"Rechercher les autres causes d’hyperprolactinémie en cas de suspicion d’un adénome à prolactine","contenu":"<p>Devant une <span class=\"kw-def\">hyperprolactinémie</span>, et <strong>avant</strong> de conclure à un <span class=\"kw-def\">adénome à prolactine</span> (prolactinome), il faut systématiquement écarter les autres causes.</p>\n      <p><strong>Étape préalable — vérifier la réalité de l'hyperprolactinémie :</strong> contrôle du dosage dans un laboratoire d'hormonologie spécialisé ; rechercher une <span class=\"kw-def\">macroprolactinémie</span> (agrégats de prolactine perturbant le dosage = fausse hyperprolactinémie, à dépister par <span class=\"kw-bio\">chromatographie</span> de la prolactine).</p>\n      <table >\n        <thead>\n          <tr><th>Cause</th><th>Mécanisme / indice diagnostique</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-ci\">Grossesse</span></strong></td>\n            <td>À éliminer par dosage de <span class=\"kw-bio\">β-hCG</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Médicaments</strong></td>\n            <td>\n              Cause de la <strong>majorité</strong> des hyperprolactinémies.<br>\n              <strong>Antagonistes dopaminergiques :</strong> <span class=\"kw-ttt\">neuroleptiques</span> (phénothiazines, <span class=\"kw-ttt\">halopéridol</span>, sulpiride) ; <span class=\"kw-ttt\">métoclopramide</span> ; <span class=\"kw-ttt\">dompéridone</span><br>\n              <strong>Autres :</strong> <span class=\"kw-ttt\">antidépresseurs</span> (tricycliques, <span class=\"kw-ttt\">IMAO</span>) ; <span class=\"kw-ttt\">œstrogènes</span> ; <span class=\"kw-ttt\">morphiniques</span> ; <span class=\"kw-ttt\">vérapamil</span> ; <span class=\"kw-ttt\">méthyldopa</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Hypothyroïdie</span> périphérique</strong></td>\n            <td>À éliminer par dosage de <span class=\"kw-bio\">TSH</span>.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Insuffisance rénale chronique</span></strong></td>\n            <td>Cause générale à rechercher.</td>\n          </tr>\n          <tr>\n            <td><strong>Hyperprolactinémie de déconnexion</strong></td>\n            <td>Compression ou section de la <span class=\"kw-def\">tige pituitaire</span> par une tumeur non prolactinique → interruption du transport de la <span class=\"kw-ttt\">dopamine</span> inhibitrice. PRL généralement <span class=\"kw-chiffre\">&lt; 150 ng/mL</span> ; ne répond pas aux agonistes dopaminergiques.</td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Repères de seuils :</strong> hyperprolactinémie des causes générales / médicamenteuses généralement modérée (<span class=\"kw-chiffre\">&lt; 150 ng/mL</span> — sauf antiémétique ou neuroleptique) ; <span class=\"kw-def\">microprolactinome</span> ≈ <span class=\"kw-chiffre\">30–100 ng/mL</span> ; <span class=\"kw-def\">macroprolactinome</span> <span class=\"kw-chiffre\">&gt; 150 ng/mL</span>. Si <strong>aucune</strong> cause n'est identifiée → <span class=\"kw-imagerie\">IRM hypophysaire</span>.</p>\n      <div class=\"callout callout-info\">\n        <strong>Piège.</strong> <span class=\"kw-def\">Macroprolactinémie</span> ≠ <span class=\"kw-def\">macroprolactinome</span>. La macroprolactinémie est une <span class=\"kw-alerte\">fausse hyperprolactinémie de laboratoire</span> (agrégats de PRL), à dépister par chromatographie <strong>avant</strong> toute imagerie.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 243 — <span class=\"kw-def\">Hypothyroïdie</span> · 264 — <span class=\"kw-def\">Insuffisance rénale chronique</span></em></p>","frequence":1}],"astuces":[],"strategie":{"urgence":"<p><strong><span class=\"kw-alerte\">Urgence</span> :</strong> l'<span class=\"kw-alerte\">apoplexie hypophysaire</span> (<span class=\"kw-clinique\">nécrose</span> ou hémorragie d'un adénome) est la seule urgence vitale de l'item, justifiant une <span class=\"kw-ttt\">PEC neurochirurgicale en urgence</span>.<br><strong>Tableau brutal :</strong> <span class=\"kw-clinique\">céphalées violentes</span>, <span class=\"kw-clinique\">hémianopsie bitemporale</span> aiguë, <span class=\"kw-alerte\">syndrome caverneux</span> (ptosis, diplopie, paralysie oculomotrice), <span class=\"kw-alerte\">syndrome confusionnel voire coma</span>.<br><strong>1er geste :</strong> <span class=\"kw-imagerie\">IRM hypophysaire</span> en urgence et traitement de l'<span class=\"kw-alerte\">insuffisance surrénale aiguë</span> (déficit corticotrope aigu).</p>","hospit":"<p><strong><span class=\"kw-alerte\">Urgence</span> neurochirurgicale :</strong> <span class=\"kw-alerte\">apoplexie hypophysaire</span> → <span class=\"kw-alerte\">hospitalisation</span> et avis neurochirurgical immédiat.<br><strong>Endocrinologue :</strong> interprétation de l'<span class=\"kw-bio\">hypophysiogramme</span> statique et des <span class=\"kw-bio\">tests hormonaux dynamiques</span>, décision thérapeutique.<br><strong>Confirmation du Cushing :</strong> <span class=\"kw-bio\">cortisol libre urinaire sur plusieurs jours consécutifs</span>, <span class=\"kw-bio\">cortisolémie à minuit</span> et <span class=\"kw-bio\">freinage standard</span> se réalisent en milieu hospitalier.<br><strong>Macroprolactinémie :</strong> contrôle de la prolactinémie en <span class=\"kw-bio\">laboratoire d'hormonologie spécialisé</span> indispensable avant toute décision.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Apoplexie hypophysaire</span> : début brutal associant <span class=\"kw-clinique\">céphalées</span> violentes, ophtalmoplégie et baisse visuelle aiguë</li><li><span class=\"kw-alerte\">Insuffisance corticotrope aiguë</span> (insuffisance surrénale aiguë) associée</li><li><span class=\"kw-clinique\">Hémianopsie bitemporale</span> par compression chiasmatique (troubles visuels)</li><li><span class=\"kw-alerte\">Syndrome caverneux</span> : ptosis, diplopie, paralysie oculomotrice</li><li><span class=\"kw-clinique\">Syndrome confusionnel voire coma</span>, photophobie (pseudo-<span class=\"kw-clinique\">syndrome méningé</span>)</li><li><span class=\"kw-alerte\">Tableau psychiatrique aigu</span> de l'hypercortisolisme : psychose hallucinatoire, tendance suicidaire</li></ul>","principes":"<p>Bilan systématique — <span class=\"kw-imagerie\">IRM hypophysaire</span>, <span class=\"kw-bio\">hypophysiogramme</span> et bilan <span class=\"kw-clinique\">ophtalmologique</span> — puis traitement selon le type d'adénome.</p><p><strong>Bilan paraclinique systématique</strong></p><ul><li><span class=\"kw-imagerie\">IRM de l'hypophyse</span> (et non <span class=\"kw-imagerie\">IRM</span> de l'encéphale), examen de référence ; <span class=\"kw-imagerie\">TDM</span> seulement en cas de <span class=\"kw-ci\">contre-indication</span> à l'<span class=\"kw-imagerie\">IRM</span></li><li>Bilan <span class=\"kw-clinique\">ophtalmologique</span> : <span class=\"kw-clinique\">champ visuel</span>, acuité visuelle, <span class=\"kw-imagerie\">fond d'œil</span>, test de Hess-Lancaster, <span class=\"kw-imagerie\">OCT</span></li><li><span class=\"kw-bio\">Hypophysiogramme</span> statique : prolactine, <span class=\"kw-bio\">ACTH</span>/cortisol <span class=\"kw-chiffre\">8h</span>/CLU <span class=\"kw-chiffre\">24h</span>, T4/<span class=\"kw-bio\">TSH</span>, IGF-1, FSH/LH, œstradiol (femme) ou testostérone (homme)</li></ul><p><strong>Traitement selon le type d'adénome</strong></p><p>Hyperprolactinémie de déconnexion (tumeur non lactotrope) : ne répond pas aux agonistes dopaminergiques → traitement chirurgical</p><ul><li><span class=\"kw-ttt\">Traitement chirurgical</span> dans la majorité des cas (adénomes non lactotropes)</li><li>Exception — <span class=\"kw-etio\">adénome à prolactine</span> : <span class=\"kw-ttt\">agonistes dopaminergiques</span> (bromocriptine) en 1re intention, seul adénome traité médicalement</li><li><span class=\"kw-ttt\">Hormonothérapie substitutive</span> des déficits antéhypophysaires associés, adaptée au cas par cas</li></ul><p><strong>Confirmer une hypersécrétion avant traitement</strong></p><ul><li><span class=\"kw-etio\">Acromégalie</span> : <span class=\"kw-def\">dépistage</span> par <span class=\"kw-bio\">IGF-1</span>, diagnostic si <span class=\"kw-bio\">GH non freinée (> 0,4 ng/mL)</span> après HGPO (le dosage isolé de GH n'a aucune valeur)</li><li><span class=\"kw-etio\">Syndrome de Cushing</span> : <span class=\"kw-chiffre\">≥ 2 tests pathologiques</span> (freinage minute <span class=\"kw-chiffre\">1 mg</span> à<span class=\"kw-chiffre\"> 23h</span>, cortisol libre urinaire, cortisol salivaire de minuit)</li><li>Étiologie du Cushing par l'<span class=\"kw-bio\">ACTH</span> : effondrée → origine surrénalienne (<span class=\"kw-imagerie\">TDM</span> des surrénales) ; normale ou élevée → ACTH-dépendant (maladie de Cushing <span class=\"kw-bio\">vs</span> sécrétion ectopique)</li></ul>","suivi":"<p><strong>Acromégalie :</strong> <span class=\"kw-ttt\">coloscopie</span> régulière (<span class=\"kw-alerte\">risque élevé de cancer colorectal</span>), <span class=\"kw-def\">surveillance</span> cardiaque (l'<span class=\"kw-alerte\">insuffisance cardiaque congestive</span> est la 1re cause de <span class=\"kw-def\">mortalité</span>), <span class=\"kw-clinique\">syndrome d'apnées du sommeil</span> et <span class=\"kw-bio\">glycémie</span>.<br><strong><span class=\"kw-clinique\">Syndrome de Cushing</span> :</strong> prévention systématique de l'<span class=\"kw-etio\">ostéoporose vertébrale</span>, surveillance de la <span class=\"kw-clinique\">TA</span>, de la <span class=\"kw-bio\">glycémie</span> et de la <span class=\"kw-bio\">kaliémie</span>.<br><strong>Déficits antéhypophysaires :</strong> adaptation de l'<span class=\"kw-ttt\">hormonothérapie substitutive</span> au cas par cas.<br><strong>Post-opératoire :</strong> surveiller l'apparition d'un <span class=\"kw-etio\">diabète insipide</span> (possible après <span class=\"kw-ttt\">chirurgie</span> hypophysaire).</p>"},"liensGlobaux":[{"href":"https://www.sfendocrino.org/item-244-adenome-hypophysaire/","label":"SFE — Item 244 adenome hypophysaire"},{"href":"https://campus.neurochirurgie.fr/article1784.html","label":"Collège — Article1784"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Suspicion d'adénome hypophysaire — Syndrome tumoral, d'hypersécrétion ou de déficit antéhypophysaire","detail":"<h4>CAT — Adénome hypophysaire — <span class=\"kw-alerte\">Red flag</span> (apoplexie) puis orientation d'une hyperprolactinémie</h4>","branches":[{"to":"q-apoplexie","label":"Symptômes / imagerie évocateurs","color":"blue"}]},{"id":"q-apoplexie","kind":"decision","label":"Début BRUTAL : céphalées violentes + ophtalmoplégie + baisse visuelle ou troubles de conscience ? — Recherche d'une apoplexie hypophysaire","branches":[{"to":"t-apoplexie","label":"Oui — apoplexie","color":"red"},{"to":"q-prl","label":"Non","color":"blue"}]},{"id":"t-apoplexie","kind":"terminal","label":"Apoplexie hypophysaire — urgence neurochirurgicale","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Céphalées violentes</span> brutales, <span class=\"kw-clinique\">photophobie</span></li><li><span class=\"kw-clinique\">Hémianopsie bitemporale</span> (compression chiasmatique aiguë)</li><li><span class=\"kw-alerte\">Syndrome caverneux</span> : <span class=\"kw-clinique\">ptosis</span>, <span class=\"kw-clinique\">diplopie</span>, <span class=\"kw-clinique\">paralysie oculomotrice</span></li><li><span class=\"kw-alerte\">Syndrome confusionnel voire coma</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-imagerie\">IRM hypophysaire</span> en <span class=\"kw-alerte\">urgence</span> (adénome en voie de <span class=\"kw-clinique\">nécrose</span> ou hémorragie)</li><li><span class=\"kw-ttt\">PEC neurochirurgicale en urgence</span></li><li>Traiter l'<span class=\"kw-alerte\">insuffisance surrénale aiguë</span> (déficit corticotrope aigu)</li></ul>"},{"id":"q-prl","kind":"decision","label":"Hyperprolactinémie confirmée (PRL > 20 ng/mL, contrôle en labo spécialisé, macroprolactinémie éliminée) ? — Sinon : autre hypersécrétion ou adénome non sécrétant","branches":[{"to":"t-chirurgie","label":"Non — autre adénome (acromégalie / Cushing / non sécrétant)","color":"amber"},{"to":"q-cause","label":"Oui — PRL > 20 ng/mL confirmée","color":"blue"}]},{"id":"t-chirurgie","kind":"terminal","label":"Adénome non lactotrope → traitement chirurgical","color":"amber","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-etio\">Acromégalie</span> (<span class=\"kw-bio\">IGF-1 élevée, GH non freinée à l'HGPO</span>), <span class=\"kw-etio\">maladie de Cushing</span>, adénome non sécrétant ou syndrome <span class=\"kw-etio\">tumoral</span></li><li>Bilan : <span class=\"kw-imagerie\">IRM hypophysaire</span> + <span class=\"kw-bio\">hypophysiogramme</span> + <span class=\"kw-clinique\">champ visuel</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Traitement chirurgical</span> dans la majorité des cas</li><li><span class=\"kw-ttt\">Hormonothérapie substitutive</span> des déficits associés (au cas par cas)</li></ul>"},{"id":"q-cause","kind":"decision","label":"Cause générale ou médicamenteuse d'hyperprolactinémie ? — Grossesse (βhCG), neuroleptiques++, hypothyroïdie périphérique (TSH), insuffisance rénale chronique","branches":[{"to":"t-cause","label":"Oui — cause retrouvée","color":"green"},{"to":"q-irm","label":"Non — pas de cause","color":"blue"}]},{"id":"t-cause","kind":"terminal","label":"Traiter la cause / arrêter le médicament","color":"green","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Traitement de la cause</span> ou <span class=\"kw-ttt\">arrêt du médicament</span> hyperprolactinémiant (<span class=\"kw-etio\">neuroleptiques</span>, <span class=\"kw-ttt\">métoclopramide</span>, œstrogènes…)</li><li><span class=\"kw-alerte\">Pas de traitement hypoprolactinémiant</span></li><li>Causes générales : <span class=\"kw-etio\">grossesse</span> (βhCG), <span class=\"kw-etio\">hypothyroïdie périphérique</span> (<span class=\"kw-bio\">TSH</span>), <span class=\"kw-etio\">insuffisance rénale chronique</span></li></ul>"},{"id":"q-irm","kind":"decision","label":"IRM hypothalamo-hypophysaire + niveau de prolactine — Aucune cause générale retrouvée","branches":[{"to":"t-prolactinome","label":"Microadénome (PRL 30-100) ou macroprolactinome (PRL > 150 ng/mL)","color":"green"},{"to":"t-deconnexion","label":"Grosse tumeur, PRL modérée < 150 ng/mL","color":"amber"}]},{"id":"t-prolactinome","kind":"terminal","label":"Prolactinome → agonistes dopaminergiques","color":"green","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Agonistes dopaminergiques</span> (bromocriptine) en 1re intention</li><li>Seul adénome traité <span class=\"kw-ttt\">médicalement</span> (exception, pas de <span class=\"kw-ttt\">chirurgie</span> d'emblée)</li><li><span class=\"kw-etio\">Macroprolactinome</span> (<span class=\"kw-chiffre\">PRL > 150 ng/mL</span>) : répond aux agonistes dopaminergiques</li></ul><h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Galactorrhée</span>, <span class=\"kw-clinique\">hypogonadisme hypogonadotrope</span> (aménorrhée, baisse de libido, infertilité)</li></ul>"},{"id":"t-deconnexion","kind":"terminal","label":"Hyperprolactinémie de déconnexion (tumeur non lactotrope)","color":"amber","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-etio\">Tumeur non prolactinique</span> comprimant la tige pituitaire (hyperprolactinémie de déconnexion)</li><li><span class=\"kw-chiffre\">PRL modérée (< 150 ng/mL)</span> malgré une grosse tumeur</li><li><span class=\"kw-alerte\">Ne répond pas aux agonistes dopaminergiques</span> → <span class=\"kw-ttt\">traitement chirurgical</span></li></ul>"}]},"cards":[{"i":"01ebc880180c","n":244,"o":"244-1","u":"Diagnostic positif","t":"Identifier les éléments d’un syndrome tumoral neuro-hypophysaire","q":"Quels sont les troubles visuels rencontrés dans le syndrome tumoral de l'adénome hypophysaire ?","a":"<ul><li><strong>Signes fonctionnels</strong> : gêne visuelle, voile devant les yeux, difficulté à fixer un point, sensation qu'il manque un mot à la lecture.</li><li><strong>Atteinte du champ visuel</strong> : initialement <strong>quadranopsie bitemporale supérieure</strong> (par compression de la partie antérieure du chiasma), évoluant vers une <strong>hémianopsie bitemporale</strong>.</li><li>L'<strong>acuité visuelle</strong> et le <strong>fond d'œil</strong> sont le plus souvent <strong>normaux</strong> au début.</li></ul>"},{"i":"bf2d53fe6bb3","n":244,"o":"244-1","u":"Diagnostic positif","t":"Identifier les éléments d’un syndrome tumoral neuro-hypophysaire","q":"Qu'est-ce que l'apoplexie hypophysaire et quels en sont les signes d'alerte dans le cadre d'un adénome hypophysaire ?","a":"<p>L'apoplexie hypophysaire est un <strong>tableau brutal</strong> lié à une <strong>nécrose ou une hémorragie</strong> au sein de l'adénome. C'est une urgence neurochirurgicale. Ses signes sont :</p><ul><li><strong>Céphalées violentes</strong>.</li><li><strong>Hémianopsie bitemporale aiguë</strong>.</li><li><strong>Photophobie</strong> (pouvant mimer un syndrome méningé).</li><li><strong>Syndrome caverneux</strong> : paralysie oculomotrice, ptosis, diplopie.</li><li><strong>Syndrome confusionnel</strong>, voire coma.</li><li><strong>Insuffisance corticotrope aiguë</strong> (insuffisance surrénale aiguë).</li><li>Possibilité d'<strong>hémorragie sous-arachnoïdienne</strong>.</li></ul>"},{"i":"d4b1219b210a","n":244,"o":"244-1","u":"Diagnostic positif","t":"Identifier les éléments d’un syndrome tumoral neuro-hypophysaire","q":"Comment définir le syndrome tumoral d'un adénome hypophysaire ?","a":"<p>Le syndrome tumoral d'un adénome hypophysaire désigne l'ensemble des manifestations cliniques dues à la <strong>compression des structures neuro-vasculaires de voisinage</strong> par la masse tumorale.</p>"},{"i":"f0d7b3ae401b","n":244,"o":"244-1","u":"Diagnostic positif","t":"Identifier les éléments d’un syndrome tumoral neuro-hypophysaire","q":"Quelles sont les caractéristiques des céphalées dans le syndrome tumoral de l'adénome hypophysaire ?","a":"<p>Les céphalées sont typiquement <strong>rétro-orbitaires</strong> et <strong>localisées</strong>.</p>"},{"i":"071bca94ea72","n":244,"o":"244-2","u":"Diagnostic positif","t":"Identifier les signes cliniques orientant vers une hypersécrétion anté-hypophysaire","q":"Comment identifier cliniquement une acromégalie, secondaire à une hypersécrétion de GH par un adénome hypophysaire ?","a":"<p>Les signes cliniques d'une <strong>acromégalie</strong> incluent :</p><ul><li><strong>Syndrome dysmorphique</strong> :<ul><li>Extrémités élargies : <strong>mains, pieds, doigts boudinés</strong>.</li><li>Visage : <strong>nez élargi, pommettes saillantes, front bombé, lèvres épaisses, prognathisme</strong>.</li><li><strong>Gigantisme</strong> si l'hypersécrétion est survenue avant la puberté.</li></ul></li><li><strong>Signes généraux</strong> : <strong>sueurs nocturnes malodorantes</strong>, céphalées, <strong>syndrome du canal carpien</strong>, arthralgies, <strong>HTA</strong> (50%), syndrome d'apnées du sommeil.</li><li><strong>Complications</strong> : <strong>diabète</strong>/intolérance au glucose, <strong>hypertrophie myocardique</strong> (1<sup>re</sup> cause de mortalité par insuffisance cardiaque), polypes coliques (risque de cancer colorectal).</li></ul>"},{"i":"0e1d05706a06","n":244,"o":"244-2","u":"Diagnostic positif","t":"Identifier les signes cliniques orientant vers une hypersécrétion anté-hypophysaire","q":"Comment un adénome thyréotrope, responsable d'une hypersécrétion de TSH, se manifeste-t-il cliniquement ?","a":"<p>Un <strong>adénome thyréotrope</strong> est une entité rare se manifestant par une <strong>hyperthyroïdie</strong>, résultat de l'hypersécrétion de TSH.</p>"},{"i":"4fd4a4b313e3","n":244,"o":"244-2","u":"Diagnostic positif","t":"Identifier les signes cliniques orientant vers une hypersécrétion anté-hypophysaire","q":"Quels sont les signes cliniques évocateurs d'un prolactinome, en tant qu'hypersécrétion anté-hypophysaire ?","a":"<p>Les signes cliniques d'un <strong>prolactinome</strong> sont :</p><ul><li><strong>Galactorrhée</strong> : provoquée (80%) ou spontanée.</li><li><strong>Hypogonadisme hypogonadotrope</strong> : la prolactine (PRL) inhibe la sécrétion pulsatile de GnRH.<ul><li>Femme : <strong>aménorrhée</strong>, oligo/spanioménorrhée, baisse de libido, dyspareunie, anovulation, infertilité.</li><li>Homme : <strong>gynécomastie</strong>, baisse de libido, dysfonction érectile.</li></ul></li><li>Os : risque d'<strong>ostéoporose</strong>.</li></ul>"},{"i":"b4b535911d9a","n":244,"o":"244-2","u":"Diagnostic positif","t":"Identifier les signes cliniques orientant vers une hypersécrétion anté-hypophysaire","q":"Quels signes cliniques orientent vers le diagnostic d'une maladie de Cushing, secondaire à l'hypersécrétion d'ACTH par un adénome hypophysaire ?","a":"<p>Les signes cliniques d'une <strong>maladie de Cushing</strong> (adénome corticotrope) sont :</p><ul><li><strong>Signes spécifiques</strong> : <strong>érythrose faciale, amyotrophie proximale</strong> (ceintures, abdomen), <strong>atrophie cutanée « en papier à cigarette », ecchymoses au moindre choc, vergetures pourpres larges (> 1 cm), horizontales</strong>.</li><li><strong>Signes moins spécifiques</strong> : <strong>prise pondérale facio-tronculaire</strong>, « <strong>bosse de bison</strong> », visage arrondi et bouffi.</li><li><strong>Comorbidités</strong> : <strong>HTA, diabète, hypokaliémie, ostéoporose</strong>, troubles gonadiques et psychiatriques.</li></ul>"},{"i":"0c30c3188825","n":244,"o":"244-3","u":"Diagnostic positif","t":"Identifier un tableau d’insuffisance anté-hypophysaire associée","q":"Comment se manifeste le déficit somatotrope et thyréotrope en cas d'insuffisance antéhypophysaire ?","a":"<ul><li><strong>Déficit somatotrope :</strong>\n<ul><li>Adulte : diminution de la masse et de la force musculaires, <strong>adiposité abdominale</strong>, asthénie.</li><li>Enfant : <strong>retard de croissance</strong>, accidents hypoglycémiques.</li></ul></li><li><strong>Déficit thyréotrope :</strong> se traduit par une <strong>hypothyroïdie centrale</strong>.</li></ul>"},{"i":"3fc5fb6bd99c","n":244,"o":"244-3","u":"Diagnostic positif","t":"Identifier un tableau d’insuffisance anté-hypophysaire associée","q":"Quelles sont les principales manifestations cliniques spécifiques du déficit de l'axe corticotrope et de l'axe gonadotrope dans le cadre d'une insuffisance antéhypophysaire ?","a":"<ul><li><strong>Axe corticotrope :</strong> asthénie, amaigrissement, anorexie, <strong>hypotension</strong>, <strong>hypoglycémie de jeûne</strong>, hyponatrémie de dilution.</li><li><strong>Axe gonadotrope :</strong>\n<ul><li>Hommes : <strong>baisse de libido</strong>, dysfonction érectile, raréfaction de la pilosité, testicules mous et petits, gynécomastie.</li><li>Femmes : <strong>aménorrhée sans bouffées de chaleur</strong>, baisse de libido, dyspareunie, anovulation, infertilité.</li><li>Les deux sexes : déminéralisation osseuse, <strong>ostéoporose</strong>.</li><li>Avant la puberté : impubérisme ou retard pubertaire.</li></ul></li></ul>"},{"i":"4d5b677bcfba","n":244,"o":"244-3","u":"Diagnostic positif","t":"Identifier un tableau d’insuffisance anté-hypophysaire associée","q":"Quels sont les signes cliniques généraux évocateurs d'une insuffisance antéhypophysaire ?","a":"<ul><li><strong>Faciès pâle</strong>, un peu vieillot</li><li>Peau mince, froide, sèche</li><li>Cheveux fins et soyeux</li><li><strong>Dépigmentation des aréoles mammaires et des organes génitaux externes</strong> (constante)</li><li>Dépilation axillaire et pubienne (chez le sujet de moins de 60 ans)</li></ul>"},{"i":"8299ac0a343b","n":244,"o":"244-3","u":"Diagnostic positif","t":"Identifier un tableau d’insuffisance anté-hypophysaire associée","q":"Quelle particularité concernant la prolactinémie peut-on observer en cas d'insuffisance antéhypophysaire causée par un adénome ?","a":"<p>La prolactinémie est le plus souvent <strong>normale ou élevée</strong>, et non basse, en raison d'une diminution du tonus dopaminergique inhibiteur sur l'hypophyse.</p>"},{"i":"c4e07a1a928f","n":244,"o":"244-3","u":"Diagnostic positif","t":"Identifier un tableau d’insuffisance anté-hypophysaire associée","q":"Quelle est l'étiologie principale de l'insuffisance antéhypophysaire dans le cadre d'un adénome hypophysaire ?","a":"<p>L'insuffisance antéhypophysaire résulte de la <strong>compression de l'antéhypophyse saine</strong> par l'adénome hypophysaire.</p>"},{"i":"0bf796477bb9","n":244,"o":"244-4","u":"Diagnostic positif","t":"Connaître les signes d’un diabète insipide","q":"Quand suspecter qu'un diabète insipide central révèle une lésion non adénomateuse ?","a":"<p>Un diabète insipide central révélant une masse de la région hypothalamo-hypophysaire doit faire suspecter une lésion <strong>non adénomateuse</strong>, telle qu'une <strong>métastase</strong>, une <strong>sarcoïdose</strong>, une <strong>histiocytose</strong>, une <strong>tuberculose</strong> ou une <strong>hypophysite auto-immune</strong>. C'est un diagnostic différentiel de l'adénome.</p>"},{"i":"211aaa47c2d6","n":244,"o":"244-4","u":"Diagnostic positif","t":"Connaître les signes d’un diabète insipide","q":"Quelles sont les caractéristiques de la polyurie observée dans un diabète insipide central ?","a":"<p>La polyurie est <strong>hypotonique</strong>, avec une diurèse supérieure à <strong>3 L/jour</strong>. Les urines sont diluées, présentant une osmolalité urinaire inférieure à <strong>300 mOsm/L</strong> (rapport U/P osm &lt; 1). La <strong>persistance nocturne</strong> (nycturie) est un signe d'organicité.</p>"},{"i":"5bc3aa01cdd8","n":244,"o":"244-4","u":"Diagnostic positif","t":"Connaître les signes d’un diabète insipide","q":"Quels sont les signes cliniques clés d'un diabète insipide central (polyuro-polydipsique) ?","a":"<ul><li><strong>Polyurie hypotonique</strong>: diurèse &gt; <strong>3 L/jour</strong>, urines diluées avec osmolalité urinaire &lt; <strong>300 mOsm/L</strong>. La <strong>nycturie</strong> est un signe d'organicité.</li><li><strong>Polydipsie intense</strong>: compensation de la polyurie par des apports hydriques importants.</li><li><strong>Hypernatrémie/déshydratation</strong>: survient uniquement si le patient n'a plus accès libre à l'eau.</li></ul>"},{"i":"74953f65e1f7","n":244,"o":"244-4","u":"Diagnostic positif","t":"Connaître les signes d’un diabète insipide","q":"Quelle est la particularité du diabète insipide central dans le contexte d'un adénome hypophysaire non traité ?","a":"<p>Un adénome hypophysaire non traité ne s'accompagne <strong>jamais</strong> de diabète insipide, car il ne touche que l'antéhypophyse. Le diabète insipide central relève d'un défaut de la posthypophyse.</p>"},{"i":"9722d593e6c6","n":244,"o":"244-4","u":"Diagnostic positif","t":"Connaître les signes d’un diabète insipide","q":"Dans quelles situations un diabète insipide peut-il survenir en lien avec un adénome hypophysaire ?","a":"<ul><li>Après une <strong>chirurgie</strong> d'un adénome hypophysaire.</li><li>Lors d'une <strong>apoplexie hypophysaire</strong>.</li></ul>"}]};